import {VariantCreate} from './variant-create.jsx';
import {StockFilters,emptyStockFilters,matchesStock} from './stock-filters.jsx';
import React, {useState,useEffect,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowUpRight,ArrowRight,ArrowLeft,Search,ShoppingBag,User,Heart,Plus,Minus,X,Check,CheckCircle2,ChevronDown,ChevronRight,SlidersHorizontal,Truck,ShieldCheck,RefreshCw,Star,Package,LayoutDashboard,Boxes,Tags,Ticket,Users,LogOut,Settings,Activity,Download,Eye,EyeOff,Pencil,Menu,RotateCcw,Wallet,Lock,Mail} from 'lucide-react';
import {CheckoutReview,ReceiptWorkspace,ReturnDetail} from './operations.jsx';
import {watchStore} from './watch-store.js';
